	@Test
	void standaloneReadsPreserveTheSourceOwnershipHandoffBeforeReusingExternalValues() {
		ValueStore store = mock(ValueStore.class);
		ValueStoreRevision ownedRevision = new ValueStoreRevision.Default(store);
		Source source = new Source() {
			@Override
			public Value lazyValue(long id, int mask) {
				calls.add(id);
				masks.add(mask);
				LmdbIRI result = new LmdbIRI(ownedRevision, "urn:scope:0:id:" + id, id);
				if (calls.size() >= 2) {
					result.markExternallyOwned();
				}
				return result;
			}

			@Override
			public Object idSpace() {
				return store;
			}
		};
		NativeProjectedBindingSet.ProjectionLayout layout = layout(1);
		LmdbQueryMemoryManager manager = manager();
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery();
				NativeResultMaterializer owner = new NativeResultMaterializerPlan(layout).open(ledger)) {
			NativeProjectedBindingSet first = new NativeProjectedBindingSet(source, layout, new long[] { 11L }, owner);
			NativeProjectedBindingSet second = new NativeProjectedBindingSet(source, layout, new long[] { 11L }, owner);
			NativeProjectedBindingSet third = new NativeProjectedBindingSet(source, layout, new long[] { 11L }, owner);
			LmdbIRI internal = (LmdbIRI) first.getValue("c0");
			assertThat(internal.isExternallyOwned()).isFalse();
			assertThat(internal.getInternalIdentity().revision().getValueStore()).isSameAs(store);
			LmdbIRI external = (LmdbIRI) second.getValue("c0");
			assertThat(source.calls).containsExactly(11L, 11L);
			assertThat(source.masks).containsExactly(MASK, MASK);
			assertThat(external).isNotSameAs(internal);
			assertThat(external.isExternallyOwned()).isTrue();
			assertThat(internal.isExternallyOwned()).isFalse();
			assertThat(external.stringValue()).isEqualTo(internal.stringValue()).isEqualTo("urn:scope:0:id:11");
			Value reused = third.getValue("c0");
			assertThat(reused.stringValue()).isEqualTo("urn:scope:0:id:11");
			assertThat(source.calls).as("direct-integration: reuse follows the normal source handoff").hasSize(2);
			assertThat(source.masks).containsExactly(MASK, MASK);
			assertThat(reused).isSameAs(external);
		}
		assertThat(manager.usedBytes()).isZero();
	}

